import AboutDetail from './AboutDetail.vue'
const sections=[
{heading:'College History',paragraphs:['The college began in 1995 with the birth of the Bachelor of Science in Computer Science (BSCS) program under the College of Commerce. The first batch consisted of two sections with about 100 students, headed by Prof. Mary O’ T. Penetrante.','During the first semester of AY 2001–2002, the Computer Science Department transferred to the College of Engineering with the newly offered Bachelor of Science in Software Engineering. At the same time, the Bachelor in Information Science and Management was offered in the College of Commerce.','At the end of AY 2002–2003, the university approved the proposal to bring BSCS, BSISM, and the new BSIT program together under one college. The College of Computer Studies began, and in the first semester of AY 2003–2004 Engr. Cirilo C. Calibjo became its first Dean. The college was housed in Mary Thomas Building.','Master in Computer Science and Master of Science in Computer Science were approved in April 2004. BSDMIA was established in 2014. In 2015, BSCS, BSIT, and BSIS received PAASCU Level 1 status.','In June 2018, the Bachelor of Science in Library and Information Science migrated to CCS. The college continues to mark its growth through its programs, accreditation, facilities, and community.']}]
</script>
